{
  "script": "Hangul",
  "title": "Your First Hangul Blocks",
  "description": "Read simple Korean syllable blocks made from four consonants and four vowels.",
  "canDo": "Read and say ㄱ, ㄴ, ㅁ, ㅅ, ㅏ, ㅗ, ㅜ, and ㅣ.",
  "intro": [
    {
      "title": "Build a block",
      "text": "Korean letters join into square syllable blocks, read from left to right and then top to bottom. A block like 가 (ga) puts its consonant on the left and its vowel on the right; vowels like ㅗ (o) and ㅜ (u) sit below the consonant instead. A silent ㅇ (no sound) goes at the start when a block begins with a vowel."
    },
    {
      "title": "Keep vowels pure",
      "text": "Say each vowel clearly and briefly, without sliding into another sound. Put the consonant and vowel together, then read the whole block as one syllable."
    }
  ],
  "letters": [
    {
      "symbol": "ㅏ",
      "readingAid": "a",
      "pronunciation": "Like the a in father, short and pure.",
      "audioText": "아",
      "forms": []
    },
    {
      "symbol": "ㅗ",
      "readingAid": "o",
      "pronunciation": "Like the o in go, but short and pure—don't add a glide.",
      "audioText": "오",
      "forms": []
    },
    {
      "symbol": "ㅜ",
      "readingAid": "u",
      "pronunciation": "Like the oo in food, short and pure.",
      "audioText": "우",
      "forms": []
    },
    {
      "symbol": "ㅣ",
      "readingAid": "i",
      "pronunciation": "Like the ee in see, short and pure.",
      "audioText": "이",
      "forms": []
    },
    {
      "symbol": "ㄱ",
      "readingAid": "g",
      "pronunciation": "A soft, unaspirated k sound, with less puff of air than English k.",
      "audioText": "가",
      "forms": []
    },
    {
      "symbol": "ㄴ",
      "readingAid": "n",
      "pronunciation": "Like n in no.",
      "audioText": "나",
      "forms": []
    },
    {
      "symbol": "ㅁ",
      "readingAid": "m",
      "pronunciation": "Like m in map.",
      "audioText": "마",
      "forms": []
    },
    {
      "symbol": "ㅅ",
      "readingAid": "s",
      "pronunciation": "Like s in see; before ㅣ, it sounds closer to sh.",
      "audioText": "사",
      "forms": []
    }
  ],
  "summary": [
    "Korean letters sit together in square syllable blocks, with vowels placed to the right or below the first consonant.",
    "Say the vowels briefly and purely, then blend each consonant and vowel into one syllable."
  ]
}

